SELECT channel, COUNT(DISTINCT p.p_promo_id) AS num_promotions, SUM(wr.wr_net_loss) AS total_net_loss, AVG(wr.wr_return_quantity) AS avg_return_qty, RANK() OVER (ORDER BY SUM(wr.wr_net_loss) DESC) AS loss_rank FROM promotion p JOIN date_dim d_start ON p.p_start_date_sk = d_start.d_date_sk JOIN web_page wp ON wp.wp_access_date_sk BETWEEN p.p_start_date_sk AND p.p_end_date_sk JOIN web_returns wr ON wr.wr_web_page_sk = wp.wp_web_page_sk CROSS JOIN UNNEST(ARRAY[IF(p.p_channel_tv = 'Y', 'TV', NULL), IF(p.p_channel_email = 'Y', 'Email', NULL), IF(p.p_channel_radio = 'Y', 'Radio', NULL), IF(p.p_channel_dmail = 'Y', 'DirectMail', NULL), IF(p.p_channel_catalog = 'Y', 'Catalog', NULL), IF(p.p_channel_press = 'Y', 'Press', NULL), IF(p.p_channel_event = 'Y', 'Event', NULL), IF(p.p_channel_demo = 'Y', 'Demo', NULL)]) AS t(channel) WHERE channel IS NOT NULL GROUP BY channel ORDER BY total_net_loss DESC
